-- {"query": "1990.sql", "dataset": "stackoverflow", "version": "v1.2", "prompt": "p1", "model": "gpt-4.1-mini", "temperature": 1.9, "max_tokens": 16384, "reasoning": "minimal", "input_tokens": 2027, "output_tokens": 940} 
with RecursiveFilter as (
    select 
        p.Id,
        p.PostTypeId,
        regexp_replace(p.Tags, '[<>]', '{''}')||COALESCE(NULLIF(p.Tags, ''), '{}') as modtags,
        u.Reputation,
        ROW_NUMBER() OVER (PARTITION BY u.Id ORDER BY p.CreationDate desc) rn
    from Posts p
    left join Users u on u.Id = p.OwnerUserId
    where p.PostTypeId in (1,2)
      and p.Score > 5
